example_solution:
class CollatzConjecture {

    static int steps(int number) {
        if (number < 1) throw new ArithmeticException("Only positive integers are allowed")

        int result = 0
        int n = number
        while (n != 1) {
            n = n % 2 == 0 ? n / 2 : 3 * n + 1
            result += 1
        }

        result
    }
}

test_code:
import spock.lang.*

class CollatzConjectureSpec extends Specification {

    def "Zero steps for one"() {
        expect:
        CollatzConjecture.steps(number) == expected

        where:
        number || expected
        1      || 0
    }

    @Ignore
    def "Divide if even"() {
        expect:
        CollatzConjecture.steps(number) == expected

        where:
        number || expected
        16     || 4
    }

    @Ignore
    def "Even and odd steps"() {
        expect:
        CollatzConjecture.steps(number) == expected

        where:
        number || expected
        12     || 9
    }

    @Ignore
    def "Large number of even and odd steps"() {
        expect:
        CollatzConjecture.steps(number) == expected

        where:
        number  || expected
        1000000 || 152
    }

    @Ignore
    def "Zero is an error"() {
        when:
        CollatzConjecture.steps(number)

        then:
        thrown(ArithmeticException)

        where:
        number = 0
    }

    @Ignore
    def "Negative value is an error"() {
        when:
        CollatzConjecture.steps(number)

        then:
        thrown(ArithmeticException)

        where:
        number = -15
    }

}
